const updateOrganization = `-- name: UpdateOrganization :one
UPDATE organizations SET
  name = COALESCE($2, name),
  code = COALESCE($3, code),
  type = COALESCE($4, type),
  active = COALESCE($5, active),
  via_organization_id = CASE WHEN $6::boolean THEN $7::uuid ELSE via_organization_id END
WHERE id = $1
RETURNING id, name, code, type, active, created_at, via_organization_id, archived_at
`

type UpdateOrganizationParams struct {
	ID                uuid.UUID   `json:"id"`
	Name              pgtype.Text `json:"name"`
	Code              pgtype.Text `json:"code"`
	Type              pgtype.Text `json:"type"`
	Active            pgtype.Bool `json:"active"`
	SetVia            bool        `json:"set_via"`
	ViaOrganizationID pgtype.UUID `json:"via_organization_id"`
}

func (q *Queries) UpdateOrganization(ctx context.Context, arg UpdateOrganizationParams) (Organization, error) {
	row := q.db.QueryRow(ctx, updateOrganization,
		arg.ID,
		arg.Name,
		arg.Code,
		arg.Type,
		arg.Active,
		arg.SetVia,
		arg.ViaOrganizationID,
	)
	var i Organization
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Code,
		&i.Type,
		&i.Active,
		&i.CreatedAt,
		&i.ViaOrganizationID,
		&i.ArchivedAt,
	)
	return i, err
}

